import requests
ids=['rs8176712','rs8176713','rs8176718','rs8176720','rs8176740','rs8176741','rs8176742','rs8176743','rs8176745','rs8176748','rs8176749','rs8176751','rs505922','rs8176719']
for rs in ids:
    try:
        r=requests.get(f'https://rest.ensembl.org/variation/human/{rs}?content-type=application/json',timeout=8)
        print(rs, r.status_code)
        if r.ok:
            maps=[m for m in r.json().get('mappings',[]) if m.get('assembly_name')=='GRCh38']
            print(maps[:1])
    except Exception as e:
        print(rs, 'ERR', type(e).__name__)
PY"
